pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised progress in the stream.
    let progress = step_index as f64 / total_items as f64;

    // Ratio of current residual to bin capacity (smoothly varying 0..1).
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;

    // Residual factor that grows with stream progress and residual ratio.
    // This encourages using bins that leave a larger fraction of space earlier
    // in the stream while still respecting the available residual.
    let residual_factor = 1.0 + 2.0 * progress * progress * residual_ratio;

    // Penalise bins that are one of many candidates (fitting_bins_count > 1).
    // Squaring emphasises the penalty for many options.
    let fit_penalty = (fitting_bins_count as f64).powi(2);

    // A light penalty that grows with the number of open bins (sqrt for smoothness).
    let open_penalty = (open_bins_count as f64).sqrt();

    // Distance from the mean residual – we prefer residuals close to the average
    // to avoid creating extreme waste.
    let mean_diff = (mean_residual - post_residual as f64).abs();

    // If we have a look‑ahead item, penalise bins that would leave insufficient
    // space for it; the penalty is quadratic to emphasise large gaps.
    let next_penalty = if next_item_size > 0 {
        let diff = (next_item_size as f64 - post_residual as f64).max(0.0);
        diff * diff
    } else {
        0.0
    };

    // Combine all components – lower score means higher priority.
    post_residual as f64 * residual_factor
        + fit_penalty
        + open_penalty
        + mean_diff
        + next_penalty
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    _step_index: usize,
    _total_items: usize,
    _open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Start with the post‑residual: smaller waste → lower score
    let mut score = post_residual as f64;

    // 1️⃣ Aggressive 2‑step lookahead: reward bins that leave space for the next item
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits → big reward, more if the residual is close to its size
            score -= 10.0 + (10.0 - diff) * 0.5;
        } else {
            // Next item would overflow → penalty proportional to how much we fall short
            score += 20.0 + diff * 0.5;
        }
    }

    // 2️⃣ Match the residual to the current mean: keep bins balanced
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score -= 0.3 * mean_diff;

    // 3️⃣ If this is the only fitting bin, give it a huge bonus
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // 4️⃣ New‑bin candidate: prefer opening a new bin only when it will help the next item
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            // New bin will accommodate the next item → strong incentive
            score -= 50.0;
        } else {
            // New bin would leave too much unused space → slight penalty
            score += 30.0;
        }
    }

    score
}

