pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placing the item
    let mut score = post_residual as f64;

    // Penalize small residuals that could lead to dead space
    if post_residual < 20 {
        score += 50.0;
    } else if post_residual < 30 {
        score += 20.0;
    }

    // Penalize if the next item would not fit in the bin after this placement
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Increase score (penalty) when many open bins exist – discourages opening new bins
    score += (open_bins_count as f64) * 5.0;

    // Slightly reward bins that are less full than the average
    let residual_diff = bin_residual as f64 - mean_residual;
    if residual_diff > 0.0 {
        score -= residual_diff * 0.1;
    }

    // Strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalized stream progress (0 at start, 1 at end)
    let t = step_index as f64 / total_items as f64;
    // Residual ratio of the candidate bin after placing the item
    let r = post_residual as f64 / bin_capacity as f64;
    // Mean residual ratio across all open bins
    let m = mean_residual / bin_capacity as f64;

    // Base score is the remaining space (lower is better)
    let mut score = post_residual as f64;

    // Reward tight packing early in the stream: high fill (1 - r) squared, scaled by (1 - t)
    score -= 15.0 * (1.0 - r).powi(2) * (1.0 - t);

    // Reward leaving very little space late in the stream: r cubed, scaled by t
    score -= 25.0 * r.powi(3) * t;

    // Penalize if the next item (if any) is unlikely to fit into this bin
    // (post_residual * next_item_size) / bin_capacity
    score -= 5.0
        * ((post_residual as f64) * (next_item_size as f64) / bin_capacity as f64);

    // Slight penalty for having many open bins (encourage closing bins sooner)
    score += 0.3 * (open_bins_count as f64);

    // Reward choosing a bin when many open bins can accommodate the item
    // (fitting_bins_count / (open_bins_count + 1))
    score -= 10.0
        * ((fitting_bins_count as f64) / (open_bins_count as f64 + 1.0));

    // Penalize if the mean residual across open bins is already high (balance usage)
    score -= 3.0 * m.powi(2);

    // Extra penalty for opening a brand‑new bin (only when the bin is empty)
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let residual = post_residual as f64;
    let capacity_f = bin_capacity as f64;
    let mut score = residual;

    let progress_sq = progress * progress;

    // Penalize large residual more as we progress
    score += residual * progress_sq;

    // Reward bins that are among few fitting options (exclude new bin candidate)
    if bin_residual != bin_capacity {
        let fit_factor = if open_bins_count > 0 {
            1.0 - (fitting_bins_count as f64) / (open_bins_count as f64)
        } else {
            0.0
        };
        score -= residual * fit_factor;
    }

    // Consider next item fit: penalize if we cannot leave space for it
    let next_fit = if next_item_size <= residual as u32 { 1.0 } else { 0.0 };
    score += (next_item_size as f64)
        * (1.0 - (residual / capacity_f))
        * (1.0 - next_fit);

    // Incorporate mean residual: reward bins that lower the mean
    score -= (mean_residual - residual) * progress_sq;

    // Penalize many open bins, scaled by remaining capacity
    let open_penalty = (open_bins_count as f64) * (1.0 - progress) * ((capacity_f - residual) / capacity_f);
    score += open_penalty;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;

    // 1️⃣ Aggressive 2‑step lookahead: penalize bins that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // cannot accommodate next item – heavy penalty
            score += 50.0;
        } else {
            // reward slack that can still hold the next item
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 0.5 * slack;
        }
    }

    // 2️⃣ Balance with mean residual across open bins
    let diff_mean = post_residual as f64 - mean_residual;
    if diff_mean > 0.0 {
        // more slack than average – reward
        score -= 0.2 * diff_mean;
    } else {
        // less slack than average – penalize
        score += 0.2 * -diff_mean;
    }

    // 3️⃣ Prioritize the last fitting bin (fitting_bins_count == 1)
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // 4️⃣ When many bins are open, penalize bins that still have large residual
    if open_bins_count > 1 {
        let residual_ratio = post_residual as f64 / bin_capacity as f64;
        score += 5.0 * residual_ratio;
    }

    // 5️⃣ Near the end of the stream squeeze bins tighter
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += 0.3 * (post_residual as f64);
    }

    // 6️⃣ New‑bin candidate: decide when opening a fresh bin is worthwhile
    if bin_residual == bin_capacity {
        if item_size > 70 || (next_item_size > 0 && next_item_size <= post_residual) {
            // large item or next item fits – reward opening a new bin
            score -= 15.0;
        } else {
            // otherwise penalize opening a new bin
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score starts with the post‑residual space.
    let mut score = post_residual as f64;

    // 1. New‑bin candidate: penalise opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 2. Last‑chance bin: heavily reward using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 3. Dead‑space penalty: if the remaining space cannot hold the next item,
    //    add a penalty proportional to the unusable gap.
    if next_item_size > 0 && post_residual < next_item_size {
        score += ((next_item_size - post_residual) as f64) * 30.0;
    }

    // 4. Open‑bins pressure: the more open bins we have, the more we push
    //    the algorithm to finish them, so add a small cost per open bin.
    score += (open_bins_count as f64) * 0.5;

    // 5. Encourage tighter packing: reduce score for bins that leave
    //    more residual space after the placement.
    score -= (post_residual as f64) * 0.1;

    // 6. Use mean residual to bias toward bins that are already more full.
    score -= mean_residual * 0.2;

    // 7. Near the end of the stream, tighten the penalty on dead space.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.95 {
        score += (post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins that leave a residual close to the next item size
    if next_item_size > 0 {
        let diff_next = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 2.0 * diff_next;
        if post_residual < next_item_size {
            score += 10.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward bins that keep the residual close to the mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score -= 1.0 * mean_diff;

    // Strongly prefer the bin if it's the only one that can fit the item
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slightly penalise having many open bins
    score += 0.5 * open_bins_count as f64;

    // Penalise opening a new bin when existing bins could take the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 5.0;
    }

    // Minor bias towards earlier steps in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}
